```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract VotingContract {
    struct Voter {
        bool voted;
        uint256 vote;
        address delegate;
    }

    struct Proposal {
        string description;
        uint256 voteCount;
    }

    address public owner;
    mapping(address => Voter) public voters;
    Proposal[] public proposals;

    event Voted(address indexed voter, uint256 proposalIndex, uint256 vote);
    event ProposalCreated(string description);
    event DelegateChanged(address indexed delegate);

    constructor() {
        owner = msg.sender;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Only the owner can perform this action.");
        _;
    }

    modifier voteExists(uint256 proposalIndex) {
        require(proposals[proposalIndex].voteCount > 0, "Vote does not exist.");
        _;
    }

    function createProposal(string memory description) public onlyOwner {
        Proposal memory newProposal = Proposal({
            description: description,
            voteCount: 0
        });
        proposals.push(newProposal);
        emit ProposalCreated(description);
    }

    function vote(uint256 proposalIndex) public voteExists(proposalIndex) {
        Voter storage sender = voters[msg.sender];
        require(!sender.voted, "Already voted.");

        sender.voted = true;
        sender.vote = proposalIndex;

        Proposal storage p = proposals[proposalIndex];
        p.voteCount += 1;

        emit Voted(msg.sender, proposalIndex, sender.vote);
    }

    function delegate(address delegateTo) public {
        Voter storage sender = voters[msg.sender];
        require(sender.voted, "Not voted yet.");

        sender.delegate = delegateTo;

        emit DelegateChanged(delegateTo);
    }

    function getWinningProposal() public view returns (uint256 winningProposalIndex) {
        uint256 winningVoteCount = 0;
        for (uint256 i = 0; i < proposals.length; i++) {
            if (proposals[i].voteCount > winningVoteCount) {
                winningVoteCount = proposals[i].voteCount;
                winningProposalIndex = i;
            }
        }
    }

    function getVoterDetails(address voter) public view returns (bool voted, uint256 vote, address delegate) {
        Voter storage voterStorage = voters[voter];
        return (voterStorage.voted, voterStorage.vote, voterStorage.delegate);
    }
}
```

This smart contract allows the owner to create proposals, cast votes, delegate votes to other addresses, and determine the winning proposal. The contract also includes events to emit notifications for voting and delegate changes. The `onlyOwner` modifier restricts certain actions to the contract owner, while the `voteExists` modifier ensures that votes are cast only for existing proposals. Voters are tracked using a `Voter` struct, and proposals are stored in an array of `Proposal` structs.

Feel free to ask if you need further details or modifications!

