```java
import java.util.List;
import java.util.Map;
import java.util.HashMap;
import java.util.stream.Collectors;

public class CarUtil {

    public static Result getMostPopularCarColor(List<Car> cars) {
        // Count the occurrences of each car color
        Map<String, Long> colorCount = cars.stream()
                .collect(Collectors.groupingBy(Car::getColor, Collectors.counting()));

        // Find the color with the maximum count
        String mostPopularColor = colorCount.entrySet().stream()
                .max(Map.Entry.comparingByValue())
                .map(Map.Entry::getKey)
                .orElse(null);

        // Return the count and color of the most popular car
        return new Result(mostPopularColor, colorCount.getOrDefault(mostPopularColor, 0L));
    }

    // Helper class to store the result
    public static class Result {
        private final String color;
        private final long count;

        public Result(String color, long count) {
            this.color = color;
            this.count = count;
        }

        public String getColor() {
            return color;
        }

        public long getCount() {
            return count;
        }
    }
}
```

In this code, we first count the occurrences of each car color using Java Streams and a HashMap. Then, we find the color with the maximum count and return the result as an instance of the `Result` class, which contains the most popular car color and its count.

